import functools
import asyncio
import inspect
from dataclasses import dataclass, field
from functools import cached_property
from typing import Any, Callable, List, Optional, Union
from typing_extensions import Literal

if asyncio.iscoroutinefunction: # simplified for repro
    from inspect import iscoroutinefunction
else:
    from asyncio import iscoroutinefunction

@dataclass
class Dependant:
    call: Optional[Callable[..., Any]] = None
    path: Optional[str] = None

    @cached_property
    def _unwrapped_call(self) -> Any:
        if self.call is None:
            return self.call

        call = self.call
        while isinstance(call, functools.partial):
            call = call.func
        return inspect.unwrap(call)

    @cached_property
    def is_gen_callable(self) -> bool:
        if inspect.isgeneratorfunction(self._unwrapped_call):
            return True
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return inspect.isgeneratorfunction(dunder_call)

    @cached_property
    def is_async_gen_callable(self) -> bool:
        if inspect.isasyncgenfunction(self._unwrapped_call):
            return True
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return inspect.isasyncgenfunction(dunder_call)

    @cached_property
    def is_coroutine_callable(self) -> bool:
        if inspect.isroutine(self._unwrapped_call):
            return iscoroutinefunction(self._unwrapped_call)
        if inspect.isclass(self._unwrapped_call):
            return False
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return iscoroutinefunction(dunder_call)

def sync_gen():
    yield 1

async def async_gen():
    yield 1

async def async_func():
    return 1

class CallableClass:
    def __call__(self):
        return 1

class AsyncCallableClass:
    async def __call__(self):
        return 1

def test_dependant_properties():
    test_cases = [
        ("sync_gen", sync_gen, True, False, False),
        ("partial_sync_gen", functools.partial(sync_gen), True, False, False),
        ("async_gen", async_gen, False, True, False),
        ("partial_async_gen", functools.partial(async_gen), False, True, False),
        ("async_func", async_func, False, False, True),
        ("partial_async_func", functools.partial(async_func), False, False, True),
        ("callable_class", CallableClass(), False, False, False),
        ("partial_callable_class", functools.partial(CallableClass()), False, False, False),
        ("async_callable_class", AsyncCallableClass(), False, False, True),
        ("partial_async_callable_class", functools.partial(AsyncCallableClass()), False, False, True),
    ]

    for name, call, is_gen, is_async_gen, is_coro in test_cases:
        dependant = Dependant(call=call, path="/test")
        print(f"{name}:")
        print(f"  is_gen_callable: {dependant.is_gen_callable} (expected {is_gen})")
        print(f"  is_async_gen_callable: {dependant.is_async_gen_callable} (expected {is_async_gen})")
        print(f"  is_coroutine_callable: {dependant.is_coroutine_callable} (expected {is_coro})")
        assert dependant.is_gen_callable == is_gen, f"{name} is_gen_callable failed"
        assert dependant.is_async_gen_callable == is_async_gen, f"{name} is_async_gen_callable failed"
        assert dependant.is_coroutine_callable == is_coro, f"{name} is_coroutine_callable failed"

